const base = $('Parsear respuesta IA Don Ramon').first().json;
const response = $input.first().json ?? {};
const pipelines = response?._embedded?.pipelines ?? response?.data?._embedded?.pipelines ?? [];
const lead = base.currentLead ?? {};

const normalize = (value) => String(value ?? '')
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .toLowerCase()
  .trim();

// IDs de las etapas "Venta ganada" / "Venta perdida" por defecto de Kommo.
// Si el pipeline de Avícola Don Ramón usa otros IDs para esas etapas, ajustar acá.
const WON_STATUS_ID = 142;
const LOST_STATUS_ID = 143;
const CLOSED_STATUS_IDS = [WON_STATUS_ID, LOST_STATUS_ID];

const pipeline = pipelines.find((item) => Number(item.id) === Number(lead.pipeline_id));
const statuses = pipeline?._embedded?.statuses ?? [];
const current = statuses.find((item) => Number(item.id) === Number(lead.status_id));

const forbiddenPattern = /ganad|perdid|venta confirm|vendid|pedido confirm|entregad|finaliz|closed/;
const candidates = statuses.filter(
  (item) => !CLOSED_STATUS_IDS.includes(Number(item.id)) && !forbiddenPattern.test(normalize(item.name))
);

// Único lugar con los nombres de etapa válidos por evento. Las claves deben
// coincidir exactamente con crm_event tal como lo emite el agente y lo valida
// 'Parsear respuesta IA Don Ramon' (allowedEvents). Si se agrega un evento
// nuevo, sumarlo en ambos nodos.
const STAGE_PATTERNS = {
  COMMERCIAL_INTEREST: [/venta potencial/, /interes comercial/, /interes/, /consulta/, /contacto inicial/, /nuevo/],
  ORDER_STARTED: [/checkout/, /link enviado/, /pedido web/, /^pedido$/, /presupuesto/],
  HUMAN_REQUIRED: [/atencion personal/, /requiere personal/, /atencion humana/, /humano/, /asesor/, /reclamo/],
  CANCELLATION_REQUESTED: [/atencion personal/, /requiere personal/, /atencion humana/, /humano/, /asesor/, /reclamo/],
};

const eventPatterns = STAGE_PATTERNS[base.crm_event] ?? [];
let target = null;
for (const pattern of eventPatterns) {
  target = candidates.find((item) => pattern.test(normalize(item.name)));
  if (target) break;
}

const shouldHaveMoved = Boolean(base.crm_event) && base.crm_event !== 'NONE';
const stageNotConfigured = shouldHaveMoved && eventPatterns.length === 0;
const stageNotFound = shouldHaveMoved && eventPatterns.length > 0 && !target;

const canMoveForward = ['HUMAN_REQUIRED', 'CANCELLATION_REQUESTED'].includes(base.crm_event)
  || !current
  || Number(target?.sort ?? 0) >= Number(current?.sort ?? 0);

const alreadyThere = Boolean(target) && Number(target.id) === Number(lead.status_id);
const leadClosed = CLOSED_STATUS_IDS.includes(Number(lead.status_id));

if (!target || !canMoveForward || leadClosed || alreadyThere) target = null;

return [{
  json: {
    ...base,
    targetPipelineId: target ? Number(pipeline.id) : null,
    targetStageId: target ? Number(target.id) : null,
    targetStageName: target?.name ?? null,
    // Visibilidad: si el evento debía mover el lead y no se encontró etapa
    // (o no hay patrones configurados para ese evento), queda registrado acá
    // en vez de fallar en silencio. Revisar los nombres de etapa en Kommo
    // contra STAGE_PATTERNS si este campo aparece seguido en las ejecuciones.
    stageResolutionWarning: stageNotConfigured
      ? `Sin patrones configurados para el evento ${base.crm_event}`
      : stageNotFound
        ? `No se encontró una etapa que coincida con el evento ${base.crm_event} en el pipeline ${pipeline?.name ?? lead.pipeline_id ?? 'desconocido'}`
        : null,
  },
}];
